INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(116400, 'ruRU', '', 'Узрите лишь осколок Альдрачи!', 24330),
(116411, 'ruRU', '', 'Древний дух, долго спавший, был пробуждён возвращением Легиона. Зло Нилаатрии должно быть изгнано из наших земель! Найди руины, что она облюбовала, и покончи с ней.', 24330),
(116412, 'ruRU', '', 'Древний дух, долго спавший, был пробуждён возвращением Легиона. Зло Нилаатрии должно быть изгнано из наших земель! Найди руины, что она облюбовала, и покончи с ней.', 24330),
(116417, 'ruRU', '', '|TInterface\\Icons\\spell_warlock_demonicportal_purple.blp:20|t%s начинает использовать |cFFFF0000|Hspell:219112|h[Теневой шквал]|h|r!', 24330),
(116418, 'ruRU', '', 'Покой...', 24330),
(116419, 'ruRU', '', 'Наконец мы отдыхаем.', 24330),
(116420, 'ruRU', '', 'Что с нами стало?', 24330),
(116421, 'ruRU', '', 'Наш народ... shu dalees-na.', 24330),
(116422, 'ruRU', '', 'Теперь я отдохну.', 24330),
(116423, 'ruRU', '', 'Магистрикс... остановите её...', 24330),
(116424, 'ruRU', '', 'Почувствуй холод могилы!', 24330),
(116425, 'ruRU', '', 'Ты станешь холодным... как мы.', 24330),
(116426, 'ruRU', '', 'Осквернитель...', 24330),
(116427, 'ruRU', '', 'Нарушитель...', 24330),
(116428, 'ruRU', '', 'Thandae-alah...', 24330),
(116448, 'ruRU', '', 'Тас''дора... Я не видел его годами! Это семейная реликвия Ветрокрылых, что висит у тебя на спине.', 24330),
(116449, 'ruRU', '', 'Моя мать передала его моей старшей сестре. Пусть он принесёт тебе больше удачи, чем принёс ей.', 24330),
(116450, 'ruRU', '', 'Если ты не будешь служить Королеве, тогда ты умрёшь!', 24330),
(116451, 'ruRU', '', 'Если ты не будешь служить Королеве, тогда ты умрёшь!', 24330),
(116452, 'ruRU', '', 'Взгляни в мою жемчужину, сухоход!', 24330),
(116453, 'ruRU', '', 'Твоя судьба заключена в моей жемчужине, $R!', 24330),
(116454, 'ruRU', '', 'Помни, $n, что Тас''дора — наследие моей семьи... МОЁ наследие. Деяния, что ты совершаешь, владея им, отражаются на мне.', 24330),
(116455, 'ruRU', '', 'Уместно, что этот лук в руках столь умелого стрелка. Я верю, что ты останешься достойным его. Не разочаруй меня.', 24330),
(116462, 'ruRU', '', 'Ванесса бросает на тебя последний взгляд, а затем уходит.', 24330),
(116465, 'ruRU', '', 'Мы пришли, как только смогли! Благодарим Свет, что ты в безопасности, пророк!', 24330),
(116466, 'ruRU', '', 'Как пожелаешь, Пророк!', 24330),
(116467, 'ruRU', '', 'Есть миф, легенда, о которой шепчутся в тёмных углах и глухих переулках.', 24330),
(116468, 'ruRU', '', 'Наверняка каждый здесь хоть раз слышал сказание о Вороньем Оке?', 24330),
(116470, 'ruRU', '', 'Это о драгоценности настолько могущественной, что никто не верит в её существование. Но уверяю тебя, она существует.', 24330),
(116471, 'ruRU', '', 'Легенда говорит, что этот камень даёт силу читать на любом языке, следовать по любой карте и, что важнее всего, расшифровывать любой код.', 24330),
(116472, 'ruRU', '', 'Но, что важнее, Воронье Око даст нам способ раскрыть секреты, скрытые в письме ШР:7. И мы знаем, где он находится.', 24330),
(116474, 'ruRU', '', 'Именно так. Мы говорим о конце секретов. Ну, чужих секретов, по крайней мере.', 24330),
(116475, 'ruRU', '', 'Лорд Кур''талос Воронья Вершина похитил око у врайкулов тысячелетия назад. Его лейтенанты использовали его во время Войны древних.', 24330),
(116495, 'ruRU', '', 'Тут осталось несколько зелий и припасов. Сделай всё необходимое, чтобы устранить угрозу!', 24330),
(116498, 'ruRU', '', 'Покажи им, что мы не сдадим Мельницу Таррен без боя!', 24330),
(116499, 'ruRU', '', 'Это место — проклятая гробница. Не будем оставаться здесь дольше, чем необходимо.', 24330),
(116502, 'ruRU', '', 'Я кое-что проверю. А пока давай убедимся, что ШР:7 не пронюхает о том, что мы на самом деле затеяли.', 24330),
(116504, 'ruRU', '', 'Я не знаю, как ты собираешься попасть на Нагльфар... корабль мёртвых врайкулов. Но если мы хотим подтвердить мои подозрения насчёт этого предмета, тебе придётся найти способ это сделать. Желательно без того, чтобы умереть, если получится.', 24330),
(116505, 'ruRU', '', 'Увидимся в Вороньем Дворе. Убедись, что за тобой не следят.', 24330),
(116507, 'ruRU', '', 'Это место кишит врагами. Попробуй найти око. Я прикрою тебя отсюда.', 24330);
